import { randomUUID as randomUUID8 } from "crypto";
import { readdir as readdir4, rm as rm6 } from "fs/promises";
import path15 from "path";

// src/domain/render-assets.ts
function cinemaRenderAssetRef(projectID, asset) {
  return {
    scope: { type: "project", projectID },
    assetID: asset.id,
    contentRevision: asset.contentRevision,
    snapshot: {
      kind: asset.kind,
      displayName: asset.displayName,
      mimeType: asset.mimeType,
      ...asset.width ? { width: asset.width } : {},
      ...asset.height ? { height: asset.height } : {},
      ...asset.durationSeconds !== undefined ? { durationSeconds: asset.durationSeconds } : {}
    }
  };
}
async function findRegisteredCinemaRenderOutput(job) {
  const previous = await getCinemaAssetLibraryOperationResult({ type: "project", projectID: job.projectID }, job.operationID);
  const parsed = CinemaAssetRecordMutationResultSchema.safeParse(previous);
  if (!parsed.success || parsed.data.asset.source !== "render")
    return;
  return cinemaRenderAssetRef(job.projectID, parsed.data.asset);
}
async function registerCinemaRenderOutput(job, outputPath) {
  const previous = await findRegisteredCinemaRenderOutput(job);
  if (previous)
    return previous;
  for (let attempt = 0;attempt < 4; attempt += 1) {
    const state = await getCinemaAssetLibraryState({ type: "project", projectID: job.projectID });
    try {
      const registered = await registerCinemaGeneratedAsset(job.projectID, {
        operationID: job.operationID,
        baseRevision: state.revision,
        sourcePath: outputPath,
        kind: "video",
        mimeType: "video/mp4",
        displayName: job.settings.outputName,
        source: "render",
        destinationFolderID: "generated-videos"
      });
      return cinemaRenderAssetRef(job.projectID, registered.asset);
    } catch (error48) {
      const recovered = await findRegisteredCinemaRenderOutput(job);
      if (recovered)
        return recovered;
      if (!(error48 instanceof ApiError) || error48.code !== "CINEMA_LIBRARY_REVISION_CONFLICT" || attempt === 3) {
        throw error48;
      }
    }
  }
  throw new Error("Render output registration could not be completed");
}

// src/domain/render-recovery.ts
var INTERRUPTIBLE_STATUSES = new Set([
  "snapshotting",
  "probing",
  "rendering",
  "registering"
]);
function isInterruptibleStatus(status) {
  return INTERRUPTIBLE_STATUSES.has(status);
}
var recoveryByCinemaRoot = new Map;
async function cleanInterruptedJobFiles(cinemaRoot3, jobID) {
  const paths = getCinemaRenderJobStoragePaths(cinemaRoot3, jobID);
  await rm6(paths.temporaryOutputPath, { force: true }).catch(() => {
    return;
  });
  const entries = await readdir4(paths.jobDirectory, { withFileTypes: true }).catch(() => []);
  await Promise.all(entries.filter((entry) => entry.isDirectory() && /^\.inputs\.[A-Za-z0-9-]+\.tmp$/.test(entry.name)).map((entry) => rm6(path15.join(paths.jobDirectory, entry.name), { recursive: true, force: true })));
}
async function recoverCinemaRenderJobs(cinemaRoot3, now = new Date().toISOString()) {
  const jobs = await listCinemaRenderJobs(cinemaRoot3);
  const queuedJobIDs = [];
  const interruptedJobIDs = [];
  for (const job of jobs) {
    if (job.status === "queued") {
      queuedJobIDs.push(job.id);
      await cleanInterruptedJobFiles(cinemaRoot3, job.id);
      continue;
    }
    if (!isInterruptibleStatus(job.status))
      continue;
    const interruptedPhase = job.status;
    if (job.status === "registering") {
      const outputAssetRef = await findRegisteredCinemaRenderOutput(job).catch(() => {
        return;
      });
      if (outputAssetRef) {
        const succeeded = {
          ...job,
          status: "succeeded",
          progress: { phase: "succeeded", percent: 100, message: "Render completed" },
          outputAssetRef,
          finishedAt: now,
          updatedAt: now
        };
        await writeCinemaRenderJob(cinemaRoot3, succeeded);
        await appendCinemaRenderJobEvent(cinemaRoot3, {
          schemaVersion: 1,
          id: `recovery-${randomUUID8()}`,
          jobID: job.id,
          type: "render-succeeded",
          createdAt: now,
          outputAssetRef,
          message: "Recovered an output that was registered before the Agent stopped."
        });
        continue;
      }
    }
    const interruptionError = {
      code: "render-interrupted",
      message: "The Agent stopped before the render job reached a terminal state.",
      retryable: true,
      diagnosticSummary: {
        phase: interruptedPhase,
        ...job.executionRuntime ? { runtime: job.executionRuntime } : {}
      }
    };
    const interrupted = {
      ...job,
      status: "interrupted",
      progress: {
        phase: "interrupted",
        message: "The Agent stopped while this render job was running."
      },
      error: interruptionError,
      finishedAt: now,
      updatedAt: now
    };
    await cleanInterruptedJobFiles(cinemaRoot3, job.id);
    await writeCinemaRenderJob(cinemaRoot3, interrupted);
    await appendCinemaRenderJobEvent(cinemaRoot3, {
      schemaVersion: 1,
      id: `recovery-${randomUUID8()}`,
      jobID: job.id,
      type: "render-interrupted",
      createdAt: now,
      error: interruptionError,
      message: "The Agent stopped before the render job reached a terminal state."
    });
    interruptedJobIDs.push(job.id);
  }
  return { queuedJobIDs, interruptedJobIDs };
}
function recoverCinemaRenderJobsOnce(cinemaRoot3) {
  const existing = recoveryByCinemaRoot.get(cinemaRoot3);
  if (existing)
    return existing;
  const recovery = recoverCinemaRenderJobs(cinemaRoot3).catch((error48) => {
    recoveryByCinemaRoot.delete(cinemaRoot3);
    throw error48;
  });
  recoveryByCinemaRoot.set(cinemaRoot3, recovery);
  return recovery;
}

